"use client"
import { ArrowDown, ArrowUp } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Card, CardContent, CardDescription } from "@atlas/ui-web/compositions/Card/Card"
import {
  Chart,
  ChartBar,
  ChartContent,
  ChartDescription,
  ChartHeader,
  ChartTitle,
} from "@atlas/ui-web/compositions/Chart/Chart"
import {
  ListItem,
  ListItemActions,
  ListItemContent,
  ListItemDescription,
  ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { SPENDING_7D, SUMMARIES, TRANSACTIONS, type ScreenState, type Summary } from "../schema"

const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" })

const stack = (gap: string): React.CSSProperties => ({
  display: "flex",
  flexDirection: "column",
  gap,
})

const sectionHeading: React.CSSProperties = {
  margin: 0,
  fontSize: "var(--atlas-text-h3)",
  fontWeight: "var(--atlas-font-weight-semibold)",
  color: "var(--atlas-foreground)",
}

function Header() {
  return (
    <header style={stack("var(--atlas-spacing-1)")}>
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h1)",
          fontWeight: "var(--atlas-font-weight-bold)",
          lineHeight: "var(--atlas-line-height-tight)",
          color: "var(--atlas-foreground)",
        }}
      >
        Dashboard
      </h1>
      <p style={{ margin: 0, fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground-muted)" }}>
        Good morning, Alex. Here is your month so far.
      </p>
    </header>
  )
}

function SummaryCard({ item }: { item: Summary }) {
  const up = item.change >= 0
  const good = up === item.upIsGood
  const Arrow = up ? ArrowUp : ArrowDown
  return (
    <Card variant="outlined" size="sm">
      <CardContent>
        <div style={stack("var(--atlas-spacing-1)")}>
          <CardDescription>{item.label}</CardDescription>
          <span
            style={{
              fontSize: "var(--atlas-text-h2)",
              fontWeight: "var(--atlas-font-weight-semibold)",
              lineHeight: "var(--atlas-line-height-tight)",
              color: "var(--atlas-foreground)",
            }}
          >
            {money.format(item.value)}
          </span>
          <div>
            <Badge
              variant={good ? "success" : "danger"}
              size="sm"
              leadingIcon={<Arrow size={12} aria-hidden="true" />}
            >
              {Math.abs(item.change)}%
            </Badge>
          </div>
          <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-subtle)" }}>
            {up ? "Up" : "Down"} {Math.abs(item.change)}% vs last month
          </span>
        </div>
      </CardContent>
    </Card>
  )
}

function SummaryGrid() {
  return (
    <section
      aria-label="Summary"
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
        gap: "var(--atlas-spacing-3)",
      }}
    >
      {SUMMARIES.map((s) => (
        <SummaryCard key={s.key} item={s} />
      ))}
    </section>
  )
}

function SpendingChart({ loading }: { loading: boolean }) {
  return (
    <Chart state={loading ? "loading" : "default"}>
      <ChartHeader>
        <ChartTitle>Spending</ChartTitle>
        <ChartDescription>Daily spending over the last 7 days.</ChartDescription>
      </ChartHeader>
      <ChartContent loadingLabel="Loading spending chart">
        {!loading && (
          <ChartBar
            aria-label="Bar chart of daily spending for the last 7 days"
            data={SPENDING_7D}
            xKey="day"
            dataKey="spent"
            label="Spent"
          />
        )}
      </ChartContent>
    </Chart>
  )
}

function Activity() {
  return (
    <section style={stack("var(--atlas-spacing-3)")}>
      <h2 style={sectionHeading}>Recent activity</h2>
      <ul style={{ ...stack("var(--atlas-spacing-2)"), listStyle: "none", margin: 0, padding: 0 }}>
        {TRANSACTIONS.map((t) => (
          <ListItem key={t.id} as="li" variant="outline" size="md">
            <ListItemContent>
              <ListItemTitle>{t.name}</ListItemTitle>
              <ListItemDescription>
                {t.category} · {t.date}
              </ListItemDescription>
            </ListItemContent>
            <ListItemActions>
              <span
                style={{
                  fontSize: "var(--atlas-text-body-sm)",
                  fontWeight: "var(--atlas-font-weight-semibold)",
                  color: t.amount > 0 ? "var(--atlas-success)" : "var(--atlas-foreground)",
                }}
              >
                {t.amount > 0 ? "+" : "−"}
                {money.format(Math.abs(t.amount))}
              </span>
            </ListItemActions>
          </ListItem>
        ))}
      </ul>
    </section>
  )
}

function LoadingActivity() {
  return (
    <section style={stack("var(--atlas-spacing-3)")} aria-hidden="true">
      <Skeleton style={{ height: "var(--atlas-spacing-6)", width: "var(--atlas-content-width-xs)" }} />
      {Array.from({ length: 5 }, (_, i) => (
        <div key={i} style={{ display: "flex", gap: "var(--atlas-spacing-3)", alignItems: "center" }}>
          <div style={{ ...stack("var(--atlas-spacing-2)"), flex: 1 }}>
            <Skeleton />
            <Skeleton style={{ width: "50%" }} />
          </div>
          <Skeleton style={{ width: "var(--atlas-spacing-12)" }} />
        </div>
      ))}
    </section>
  )
}

function LoadingSummary() {
  return (
    <section
      aria-hidden="true"
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
        gap: "var(--atlas-spacing-3)",
      }}
    >
      {SUMMARIES.map((s) => (
        <Card key={s.key} variant="outlined" size="sm">
          <CardContent>
            <div style={stack("var(--atlas-spacing-2)")}>
              <Skeleton style={{ width: "50%" }} />
              <Skeleton style={{ height: "var(--atlas-spacing-6)" }} />
              <Skeleton style={{ width: "var(--atlas-spacing-12)" }} />
            </div>
          </CardContent>
        </Card>
      ))}
    </section>
  )
}

export function Dashboard({ state, onRetry }: { state: ScreenState; onRetry: () => void }) {
  return (
    <div
      aria-busy={state === "loading"}
      style={{
        ...stack("var(--atlas-spacing-6)"),
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlockEnd: "var(--atlas-spacing-6)",
      }}
    >
      <Header />
      {state === "failed" && (
        <Alert
          variant="danger"
          title="Couldn't load your dashboard"
          description="Check your connection and try again."
          actions={
            <Button variant="outline" size="sm" onClick={onRetry}>
              Retry
            </Button>
          }
        />
      )}
      {state === "loading" && (
        <>
          <p role="status" style={{ margin: 0, position: "absolute", insetInlineStart: "-9999px" }}>
            Loading your dashboard
          </p>
          <LoadingSummary />
          <SpendingChart loading />
          <LoadingActivity />
        </>
      )}
      {state === "loaded" && (
        <>
          <SummaryGrid />
          <SpendingChart loading={false} />
          <Activity />
        </>
      )}
    </div>
  )
}

